class Model(torch.nn.Module):
    def forward(self, x, src):
        return torch.slice_scatter(x, src, dim=0, start=1, end=3, step=1)

x = torch.arange(4, dtype=torch.float32)
src = torch.full((2,), 99.0)
check(Model(), (x, src))

class Model(torch.nn.Module):
    def forward(self, x, src):
        return torch.slice_scatter(x, src, dim=0, start=None, end=2, step=1)

x = torch.arange(4, dtype=torch.float32)
src = torch.full((2,), 99.0)
check(Model(), (x, src))

class Model(torch.nn.Module):
    def forward(self, x, src):
        return torch.slice_scatter(x, src, dim=-1, start=0, end=2, step=1)

x = torch.arange(8, dtype=torch.float32).reshape(2, 4)
src = torch.full((2, 2), 99.0)
D = torch.export.Dim('rows', min=3)
check(Model(), (x, src), dynamic_shapes=({1: D}, {}))

